{
  "title": "React Hooks Mastery",
  "moduleTitle": "Using useState and useEffect",
  "xpReward": 250,
  "watch": {
    "url": "",
    "duration": "12:00",
    "transcript": [
      {
        "timestamp": "0:00",
        "line": "Welcome to the React Hooks module. Today we’ll dive into useState and useEffect."
      },
      {
