        "description": "Share values between components without prop drilling.",
        "resource": "https://reactjs.org/docs/hooks-reference.html#usecontext"
      },
      {
        "title": "useReducer",
        "description": "Manage complex state logic with a reducer function.",
        "resource": "https://reactjs.org/docs/hooks-reference.html#usereducer"
      }
    ]
