      {
        "id": "t2",
        "description": "Adding a todo updates the list",
        "hint": "Simulate typing 'Buy milk' and clicking Add",
        "input": "render(<TodoList />); fireEvent.change(input, { target: { value: 'Buy milk' } }); fireEvent.click(addButton);",
        "expected_output": "Buy milk"
      },
      {
        "id": "t3",
        "description": "Todos persist after re-render via localStorage",
        "hint": "Add a todo, unmount and remount the component, then check list",
        "input": "render(<TodoList />); fireEvent.change(input, { target: { value: 'Read book' } }); fireEvent.click(addButton); cleanup(); render(<TodoList />);",
        "expected_output": "Read book"
      },
